namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
    public DateTime SubmittedAt { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Exploration of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Understanding the fundamental laws of the universe." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and critical analysis of texts." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, DepartmentId = 1, Title = "Introduction to Programming", Code = "CS101", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented principles.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, Title = "Data Structures and Algorithms", Code = "CS201", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs. Algorithm analysis and design techniques.", Credits = 4, Schedule = "Tue/Thu 10:30-11:45 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm optimization and has published over 30 papers in top CS conferences.", IsFeatured = false },
            new() { Id = 3, DepartmentId = 1, Title = "Web Development", Code = "CS310", Description = "Full-stack web development covering HTML, CSS, JavaScript, and server-side frameworks. Build real-world web applications.", Credits = 3, Schedule = "Mon/Wed 2:00-3:15 PM", InstructorName = "Prof. Lisa Park", InstructorBio = "Prof. Park spent 10 years in the tech industry before joining academia. She specializes in modern web technologies.", IsFeatured = true },
            new() { Id = 4, DepartmentId = 1, Title = "Database Systems", Code = "CS340", Description = "Relational database design, SQL, normalization, and transaction processing. Introduction to NoSQL databases.", Credits = 3, Schedule = "Tue/Thu 1:00-2:15 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres has extensive experience in distributed database systems and data engineering.", IsFeatured = false },

            // Mathematics
            new() { Id = 5, DepartmentId = 2, Title = "Calculus I", Code = "MATH101", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00-10:50 AM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson is an award-winning mathematics educator with a passion for making calculus accessible to all students.", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, Title = "Linear Algebra", Code = "MATH220", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 9:00-10:15 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim's research focuses on applied linear algebra and numerical methods.", IsFeatured = false },
            new() { Id = 7, DepartmentId = 2, Title = "Probability and Statistics", Code = "MATH301", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 11:00 AM-12:15 PM", InstructorName = "Dr. Anna Petrov", InstructorBio = "Dr. Petrov combines theoretical statistics with real-world data science applications in her teaching.", IsFeatured = false },

            // Physics
            new() { Id = 8, DepartmentId = 3, Title = "General Physics I", Code = "PHYS101", Description = "Mechanics, thermodynamics, and waves. Calculus-based introduction to classical physics.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00-11:50 AM", InstructorName = "Dr. David Chang", InstructorBio = "Dr. Chang is an experimental physicist with research in condensed matter physics.", IsFeatured = false },
            new() { Id = 9, DepartmentId = 3, Title = "Electromagnetism", Code = "PHYS202", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 2:00-3:15 PM", InstructorName = "Dr. Maria Santos", InstructorBio = "Dr. Santos has contributed to breakthrough research in electromagnetic theory and applications.", IsFeatured = true },
            new() { Id = 10, DepartmentId = 3, Title = "Quantum Mechanics", Code = "PHYS310", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Mon/Wed 3:30-4:45 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is a theoretical physicist exploring quantum information and computation.", IsFeatured = false },

            // English
            new() { Id = 11, DepartmentId = 4, Title = "English Composition", Code = "ENG101", Description = "Develop clear, effective writing skills. Focus on argumentation, research, and academic writing.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00-1:50 PM", InstructorName = "Prof. Catherine Moore", InstructorBio = "Prof. Moore is a published author and writing instructor with 20 years of teaching experience.", IsFeatured = false },
            new() { Id = 12, DepartmentId = 4, Title = "American Literature", Code = "ENG205", Description = "Survey of American literary works from the colonial period to the present day.", Credits = 3, Schedule = "Tue/Thu 11:00 AM-12:15 PM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright specializes in 20th-century American fiction and has authored three books on the subject.", IsFeatured = false },
            new() { Id = 13, DepartmentId = 4, Title = "Creative Writing", Code = "ENG310", Description = "Workshop-based course in fiction, poetry, and creative nonfiction. Develop your unique voice as a writer.", Credits = 3, Schedule = "Wed 6:00-8:45 PM", InstructorName = "Prof. Rachel Green", InstructorBio = "Prof. Green is an award-winning poet and novelist who brings real-world publishing experience to the classroom.", IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.ToLower();
            query = query.Where(c =>
                c.Title.ToLower().Contains(term) ||
                c.Code.ToLower().Contains(term) ||
                c.Description.ToLower().Contains(term) ||
                c.InstructorName.ToLower().Contains(term));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        request.SubmittedAt = DateTime.UtcNow;
        _enrollmentRequests.Add(request);
    }
}

