+            new() { Id = 9, DepartmentId = 3, Title = "Electromagnetism", Code = "PHYS202", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 2:00-3:15 PM", InstructorName = "Dr. Maria Santos", InstructorBio = "Dr. Santos has contributed to breakthrough research in electromagnetic theory and applications.", IsFeatured = true },
