@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@using Microsoft.AspNetCore.Http
@inject CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="searchTerm" class="form-control" placeholder="Search courses..." value="@SearchTerm" />
    </div>
    <div class="col-md-4">
        <select name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(SearchTerm, DepartmentId);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <div class="row">
        @foreach (var course in courses)
        {
            var dept = CatalogService.GetDepartment(course.DepartmentId);
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.Title</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.Code &middot; @course.Credits credits &middot; @dept?.Name</h6>
                        <p class="card-text">@course.Schedule</p>
                    </div>
                    <div class="card-footer">
                        <a href="/courses/@course.Id" class="btn btn-primary btn-sm">Details</a>
                        <a href="/enroll?courseId=@course.Id" class="btn btn-outline-secondary btn-sm">Enroll</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? SearchTerm { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/courses/{id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>Course Details - University Course Catalog</PageTitle>

@{
    var course = CatalogService.GetCourse(Id);
}

@if (course is null)
{
    <div class="alert alert-warning">Course not found.</div>
}
else
{
    var dept = CatalogService.GetDepartment(course.DepartmentId);

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item active">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Title</h1>
    <span class="badge bg-secondary mb-3">@course.Code</span>
    <span class="badge bg-info mb-3">@course.Credits Credits</span>
    <span class="badge bg-primary mb-3">@dept?.Name</span>

    <div class="row mt-4">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4 class="mt-4">Schedule</h4>
            <p><i class="bi bi-clock"></i> @course.Schedule</p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Instructor</h5>
                    <h6>@course.InstructorName</h6>
                    <p class="text-muted">@course.InstructorBio</p>
                </div>
            </div>
            <a href="/enroll?courseId=@course.Id" class="btn btn-success w-100 mt-3">Enroll in This Course</a>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h1 class="mb-4">Course Enrollment</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for 
        <strong>@(CatalogService.GetCourse(Model.CourseId)?.Title ?? "the selected course")</strong> has been received.</p>
        <a href="/courses" class="btn btn-primary">Back to Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <EditForm Model="Model" FormName="enrollment" method="post" OnValidSubmit="HandleSubmit">
                <div class="mb-3">
                    <label for="studentName" class="form-label">Student Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                </div>
                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
                </div>
                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                        <option value="0">-- Select a Course --</option>
                        @foreach (var course in CatalogService.GetCourses(null, null))
                        {
                            <option value="@course.Id">@course.Code - @course.Title</option>
                        }
                    </InputSelect>
                </div>
                <button type="submit" class="btn btn-primary">Submit Enrollment</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool _submitted;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(Model);
        _submitted = true;
    }
}

